# Known weight-management medicines and how often they are taken. Other products stay "as directed"
# until the practice sets them in the catalogue.
KNOWN_FREQUENCIES = {'semaglutide': 'weekly', 'tirzepatide': 'weekly', 'liraglutide': 'daily'}


def set_known_frequencies(apps, schema_editor):
    MedicationProduct = apps.get_model('care', 'MedicationProduct')
    for product in MedicationProduct.objects.all():
        frequency = KNOWN_FREQUENCIES.get(product.name.strip().split(' ')[0].casefold())
        if frequency:
            product.dose_frequency = frequency
            product.save(update_fields=['dose_frequency'])


